import React from 'react';

const Dashboard = ({ stats, notifications, setActiveTab }) => {
    return (
        <div style={{ padding: '30px', maxWidth: '1200px', margin: '0 auto' }}>
            <h1 style={{ fontSize: '2rem', color: '#1f2937', marginBottom: '30px' }}>Dashboard Overview</h1>

            {/* Stats Grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '40px' }}>
                <div 
                    onClick={() => setActiveTab('matches')}
                    style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', borderLeft: '4px solid #e11d48', cursor: 'pointer', transition: 'transform 0.2s' }}
                    onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.02)'}
                    onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                >
                    <h3 style={{ margin: '0 0 10px 0', color: '#6b7280', fontSize: '1rem' }}>Total Matches</h3>
                    <p style={{ margin: 0, fontSize: '2rem', fontWeight: 'bold', color: '#1f2937' }}>{stats?.totalMatches || 0}</p>
                </div>

                <div 
                    onClick={() => setActiveTab('matches')}
                    style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', borderLeft: '4px solid #8b5cf6', cursor: 'pointer', transition: 'transform 0.2s' }}
                    onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.02)'}
                    onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                >
                    <h3 style={{ margin: '0 0 10px 0', color: '#6b7280', fontSize: '1rem' }}>Accepted Matches</h3>
                    <p style={{ margin: 0, fontSize: '2rem', fontWeight: 'bold', color: '#1f2937' }}>{stats?.acceptedMatches || 0}</p>
                </div>

                <div 
                    onClick={() => setActiveTab('requests')}
                    style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', borderLeft: '4px solid #10b981', cursor: 'pointer', transition: 'transform 0.2s' }}
                    onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.02)'}
                    onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                >
                    <h3 style={{ margin: '0 0 10px 0', color: '#6b7280', fontSize: '1rem' }}>Pending Requests</h3>
                    <p style={{ margin: 0, fontSize: '2rem', fontWeight: 'bold', color: '#1f2937' }}>{stats?.pendingRequests || 0}</p>
                </div>

                <div 
                    onClick={() => setActiveTab('chat')}
                    style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', borderLeft: '4px solid #3b82f6', cursor: 'pointer', transition: 'transform 0.2s' }}
                    onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.02)'}
                    onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                >
                    <h3 style={{ margin: '0 0 10px 0', color: '#6b7280', fontSize: '1rem' }}>Unread Messages</h3>
                    <p style={{ margin: 0, fontSize: '2rem', fontWeight: 'bold', color: '#1f2937' }}>{stats?.unreadMessages || 0}</p>
                </div>
            </div>

            {/* Live Notifications Feed */}
            <div style={{ backgroundColor: 'white', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', overflow: 'hidden' }}>
                <div style={{ padding: '20px', borderBottom: '1px solid #e5e7eb', backgroundColor: '#f9fafb' }}>
                    <h2 style={{ margin: 0, fontSize: '1.2rem', color: '#1f2937', display: 'flex', alignItems: 'center' }}>
                        <span style={{ display: 'inline-block', width: '10px', height: '10px', backgroundColor: '#10b981', borderRadius: '50%', marginRight: '10px', animation: 'pulse 2s infinite' }}></span>
                        Live Activity Feed
                    </h2>
                </div>
                <div style={{ padding: '20px' }}>
                    {(!notifications || notifications.length === 0) ? (
                        <p style={{ color: '#6b7280', textAlign: 'center', padding: '20px' }}>Waiting for real-time events via RabbitMQ...</p>
                    ) : (
                        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                            {notifications.map((notif, index) => (
                                <li key={index} style={{ padding: '15px 0', borderBottom: index !== notifications.length - 1 ? '1px solid #f3f4f6' : 'none', display: 'flex', alignItems: 'flex-start' }}>
                                    <div style={{ marginRight: '15px', fontSize: '1.5rem' }}>
                                        {notif.type === 'location' ? '📍' : notif.type === 'message' ? '💬' : '❤️'}
                                    </div>
                                    <div>
                                        <p style={{ margin: '0 0 5px 0', fontWeight: 'bold', color: '#1f2937' }}>{notif.title}</p>
                                        <p style={{ margin: 0, color: '#6b7280', fontSize: '0.9rem' }}>{notif.message}</p>
                                    </div>
                                    <span style={{ marginLeft: 'auto', fontSize: '0.8rem', color: '#9ca3af' }}>{notif.time || 'Just now'}</span>
                                </li>
                            ))}
                        </ul>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
